-- =============================================================================
-- ERP Accesalia — Carga de las personas de contrata y de su historia laboral
--
-- ORIGEN: la hoja `contratas_personas_revision.xlsx`, revisada a mano por
-- Monica el 10-sep-2026 (86 correcciones y 25 notas), mas lo que aporto en la
-- conversacion. Las decisiones que salen de una nota van comentadas en el
-- script que genero este fichero (scratchpad/preparar_carga.py), con el numero
-- de fila de cada una.
--
-- NO SE TOCA `contrata_contactos`: se queda entera, como copia de seguridad,
-- hasta que estas dos tablas se den por buenas.
-- NO SE TOCA `contratas.notas_comercial`: lleva acuerdos con Ecobalance,
-- honorarios y formas de pago. Solo se escribe donde hay hueco.
--
-- Los uuid vienen escritos: si esto se ejecutara dos veces por error, la
-- segunda no duplicaria nada (on conflict do nothing).
--
-- Todo en una transaccion: entra entero o no entra nada.
-- =============================================================================
begin;

-- 1. Contrata nueva ---------------------------------------------------------
select 'MOLINS', 'otra', true, 'dada de alta el 10-sep-2026 solo para colocar a Jose Luis Jimenez; faltan CIF, razon social y datos de contacto'
 where not exists (select 1 from contratas where nombre = 'MOLINS');

-- 2. Las personas -----------------------------------------------------------
on conflict (id) do nothing;

-- 3. Los puestos ------------------------------------------------------------
on conflict (id) do nothing;

-- 4. Notas y pendientes de las contratas, solo donde hay hueco --------------
update contratas set notas_fiabilidad = 'Denunciado por estafa y en juicios.' where nombre = '⛔ INVER' and notas_fiabilidad is null;
update contratas set pendiente = 'empresa de reformas a medias entre David Faraco y otros dos socios: uno de apellido Oliver y otro por confirmar' where nombre = 'SACEFA' and pendiente is null;
update contratas set pendiente = 'en la ficha consta ''Roberto Corral 639680439'' como contacto comercial y no esta en la lista de personas; suenan a dos hermanos (de ahi ''Brother''), confirmar y darlo de alta' where nombre = 'SAACO BROTHER' and pendiente is null;
update contratas set notas_fiabilidad = 'Empresa de ascensores en la calle de al lado de la oficina de Alhambra.' where nombre = 'ALTAIR ASCENSORES' and notas_fiabilidad is null;

-- 5. Comprobacion antes de cerrar -------------------------------------------
do $$
declare n_per int; n_pue int; n_huerfano int;
begin
  select count(*) into n_per from contrata_personas;
  select count(*) into n_pue from contrata_puestos_persona;
  select count(*) into n_huerfano from contrata_puestos_persona where contrata_id is null;
  raise notice 'personas: %, puestos: %, puestos sin contrata: %', n_per, n_pue, n_huerfano;
  if n_huerfano > 0 then
    raise exception 'hay % puestos apuntando a una contrata que no existe', n_huerfano;
  end if;
end $$;

commit;
